function first<T>(arr: T[]): T | undefined {
  return arr[0];
}

function identity<T>(value: T): T {
  return value;
}

interface Pair<K, V> {
  key: K;
  value: V;
}

const num = first([1, 2, 3]);
const str = first(['a', 'b', 'c']);
console.log(`First number: ${num}`);
console.log(`First string: ${str}`);

const pair: Pair<string, number> = { key: 'age', value: 30 };
console.log(`Pair: ${pair.key} = ${pair.value}`);

const id = identity<string>('TypeScript');
console.log(`Identity: ${id}`);
